const fs = require('fs');
const data = fs.readFileSync(0);
let ptr = 0;
const dataLen = data.length;

function nextInt() {
    while (ptr < dataLen && data[ptr] <= 32) ptr++;
    let num = 0;
    while (ptr < dataLen && data[ptr] > 32) {
        num = num * 10 + (data[ptr] - 48);
        ptr++;
    }
    return num;
}

const N = nextInt();
const K = nextInt();

const head = new Int32Array(N);
head.fill(-1);

const edgeCount = 2 * (N - 1);
const to = new Int32Array(edgeCount);
const nxt = new Int32Array(edgeCount);

let ec = 0;
for (let i = 0; i < N - 1; i++) {
    const a = nextInt() - 1;
    const b = nextInt() - 1;

    to[ec] = b;
    nxt[ec] = head[a];
    head[a] = ec++;

    to[ec] = a;
    nxt[ec] = head[b];
    head[b] = ec++;
}

const parent = new Int32Array(N);
parent.fill(-1);

const order = new Int32Array(N);
let qh = 0, qt = 0;
order[qt++] = 0;

while (qh < qt) {
    const u = order[qh++];

    for (let e = head[u]; e !== -1; e = nxt[e]) {
        const v = to[e];
        if (v === parent[u]) continue;

        parent[v] = u;
        order[qt++] = v;
    }
}

const NEG = -1000000000;
const INF = 1000000000;

const mx = new Int32Array(N);
const dm = new Int32Array(N);

function feasible(R) {
    mx.fill(0);
    dm.fill(INF);

    let centers = 0;

    for (let i = N - 1; i >= 0; i--) {
        const u = order[i];

        let mu = mx[u];
        let du = dm[u];

        if (mu !== NEG && mu + du <= R) {
            mu = NEG;
        }

        if (mu === R) {
            centers++;
            if (centers > K) return false;

            mu = NEG;
            du = 0;
        }

        mx[u] = mu;
        dm[u] = du;

        const p = parent[u];

        if (p !== -1) {
            const childMx = mu + 1;
            if (childMx > mx[p]) mx[p] = childMx;

            const childDm = du + 1;
            if (childDm < dm[p]) dm[p] = childDm;
        }
    }

    if (mx[0] !== NEG) centers++;

    return centers <= K;
}

let lo = -1;
let hi = N;

while (hi - lo > 1) {
    const mid = (lo + hi) >> 1;

    if (feasible(mid)) {
        hi = mid;
    } else {
        lo = mid;
    }
}

